% Strategy: infer the multiset of pairwise sums by sorting all pair sums of unknown bale weights; use a permutation-style assignment of observed weights to the n choose 2 pair-sum positions, then recover the bale weights through a canonical order-breaking reconstruction.

int: n;
array[1..n*(n-1) div 2] of int: weights;

array[1..n] of var min(weights) div (n-1) .. max(weights): bales;

array[1..n*(n-1) div 2] of var 1..n*(n-1) div 2: pos;

constraint alldifferent(pos);

constraint
  forall(k in 1..n*(n-1) div 2)(
    weights[k] = bales[1] + bales[2]
  );

% Canonical reconstruction from the sorted pair sums:
% let s1 be the smallest pair sum = bales[1] + bales[2]
% and s2 be the next smallest pair sum = bales[1] + bales[3]
% then all other bales are determined by these via pair-sum consistency.
constraint bales[1] <= bales[2];
constraint forall(i in 2..n-1)(bales[i] <= bales[i+1]);

constraint
  let {
    int: m = n*(n-1) div 2
  } in
    weights[1] = bales[1] + bales[2] /\
    weights[2] = bales[1] + bales[3];

constraint
  forall(i in 1..n-2, j in i+1..n)(
    exists(k in 1..n*(n-1) div 2)(
      weights[k] = bales[i] + bales[j]
    )
  );

solve satisfy;

output ["{\"bales\":", show(bales), "}"];

