equivalent.code:
% Strategy: use inverse seating-position variables (position_of) plus seat-at-position view to model the circular adjacency constraints directly.
include "globals.mzn";

int: n = 6;

int: Andrew = 0;
int: Betty = 1;
int: Cara = 2;
int: Dave = 3;
int: Erica = 4;
int: Frank = 5;

array[0..n-1, 0..1] of int: prefs = array2d(0..n-1, 0..1, [
    Dave, Frank,    % Andrew
    Cara, Erica,    % Betty
    Betty, Frank,   % Cara
    Andrew, Erica,  % Dave
    Betty, Dave,    % Erica
    Andrew, Cara    % Frank
]);

array[0..n-1] of var 0..n-1: x;           % x[i] = guest sitting in seat i
array[0..n-1] of var 0..n-1: pos_of;      % pos_of[g] = seat index of guest g

constraint alldifferent(x);
constraint alldifferent(pos_of);

constraint forall(g in 0..n-1) (
    x[pos_of[g]] = g
);

constraint forall(s in 0..n-1) (
    let {
        var 0..n-1: g = x[s]
    } in
        ((x[(s - 1 + n) mod n] = prefs[g, 0]) \/ (x[(s - 1 + n) mod n] = prefs[g, 1])) /\
        ((x[(s + 1) mod n] = prefs[g, 0]) \/ (x[(s + 1) mod n] = prefs[g, 1]))
