% Strategy: dual-view assignment model — each letter is assigned to exactly one block, and each word is enforced by pairwise distinct-block constraints across its letters.
int: num_blocks;
int: num_letters;
int: num_sides;
array[1..num_letters] of string: words_str;
array[1..num_letters] of var 0..num_blocks-1: dice;

constraint num_letters = length(words_str);
constraint num_blocks * num_sides >= num_letters;

% Every letter must be placed on exactly one block, and each block holds at most num_sides letters.
constraint forall(b in 0..num_blocks-1) (
  sum(i in 1..num_letters)(bool2int(dice[i] = b)) <= num_sides
);

% Each word must be spellable from the blocks: all letters in a word come from different blocks.
constraint
  forall(w in 1..num_letters) (
    let {
      int: wl = string_length(words_str[w]),
      array[1..wl] of int: letters =
        [ord(words_str[w][k]) - ord("A") + 1 | k in 1..wl]
    } in
      forall(i, j in 1..wl where i < j) (
        dice[letters[i]] != dice[letters[j]]
      )
  );

solve satisfy;

output ["{\"dice\":", show(dice), "}"];

