equivalent.code:
% Strategy: represent the rack as a permutation of devices by position; use pairwise absolute-position cable lengths and compute total as a derived variable.
int: n;
array[1..n] of string: devices;
array[1..8, 1..3] of string: cable_struct;

array[1..n] of var 1..n: pos;
array[1..n] of var 1..n: device_at_pos;
var int: final_sum;

constraint all_different(pos);
constraint all_different(device_at_pos);

constraint forall(i in 1..n)(
  device_at_pos[pos[i]] = i
);

constraint final_sum =
  sum(e in 1..8)(
    abs(pos[sum(i in 1..n)(bool2int(devices[i] = cable_struct[e,1]) * i)] -
        pos[sum(i in 1..n)(bool2int(devices[i] = cable_struct[e,2]) * i)])
  );

solve satisfy;

output ["{\"final_sum\": ", show(final_sum), "}"];

