% Strategy: dual orientation with corner variables and pairwise forbidden-overlap/separation disjunctions; derive right/top from left/bottom to preserve exact feasibility while changing the modeling viewpoint from center-based encoding.
int: n_containers;
int: deck_length;
int: deck_width;
array[1..n_containers] of int: length;
array[1..n_containers] of int: width;
array[1..n_containers] of int: classes;
array[1..2, 1..2] of int: separation;

array[1..n_containers] of var 0..deck_length: left;
array[1..n_containers] of var 0..deck_width: bottom;
array[1..n_containers] of var 0..deck_length: right;
array[1..n_containers] of var 0..deck_width: top;

constraint forall(i in 1..n_containers) (
  right[i] = left[i] + length[i] /\
  top[i] = bottom[i] + width[i] /\
  right[i] <= deck_length /\
  top[i] <= deck_width
);

constraint forall(i, j in 1..n_containers where i < j) (
  right[i] + separation[classes[i], classes[j]] <= left[j] \/
  right[j] + separation[classes[j], classes[i]] <= left[i] \/
  top[i] + separation[classes[i], classes[j]] <= bottom[j] \/
  top[j] + separation[classes[j], classes[i]] <= bottom[i]
);

solve satisfy;

