  forall(t in TEAMS, d in DAYS) (
    if opp[t,d] = BYE then
      where[t,d] = -1
    else
      where[t,d] in {-2,0}
    endif
  );

constraint
  forall(t in TEAMS, d in DAYS) (
    (opp[t,d] = BYE) <-> (where[t,d] = -1)
  );

constraint
  forall(t in TEAMS, d in DAYS) (
    opp[t,d] != BYE ->
      ((where[t,d] = 0 /\ where[opp[t,d],d] = -2) \/
       (where[t,d] = -2 /\ where[opp[t,d],d] = 0))
  );

constraint
  forall(t in TEAMS, d in DAYS where opp[t,d] != BYE) (
    opp[opp[t,d], d] = t
