% Strategy: dual timetable reformulation using opponent and home/away decision arrays; derive config and where from them, rather than modeling config directly.
int: n_days;
int: n_teams;

set of int: DAYS = 1..n_days;
set of int: TEAMS = 1..n_teams;

int: BYE = 0;

array[1..n_teams, 1..n_days] of var 0..n_teams: opp;
array[1..n_teams, 1..n_days] of var -2..0: where;

array[1..n_days, 1..n_teams] of var 0..n_teams: config;
array[1..n_days, 1..n_teams] of var -2..0: where_out;

constraint n_teams = 9;
constraint n_days = 18;

% Opponent/home-away consistency and symmetry
constraint
  forall(t in TEAMS, d in DAYS) (
    if opp[t,d] = BYE then
      where[t,d] = -1
    else
      where[t,d] in {-2,0}
    endif
  );

constraint
  forall(t in TEAMS, d in DAYS) (
    (opp[t,d] = BYE) <-> (where[t,d] = -1)
  );

constraint
  forall(t in TEAMS, d in DAYS) (
    opp[t,d] != BYE ->
      ((where[t,d] = 0 /\ where[opp[t,d],d] = -2) \/
       (where[t,d] = -2 /\ where[opp[t,d],d] = 0))
  );

constraint
  forall(t in TEAMS, d in DAYS where opp[t,d] != BYE) (
    opp[opp[t,d], d] = t
  );

constraint
  forall(t in TEAMS, d in DAYS where opp[t,d] != BYE) (
    opp[t,d] != t
  );

% Each team plays at most one opponent per day
constraint
  forall(t in TEAMS, d in DAYS) (
    opp[t,d] != BYE -> opp[t,d] >= 1 /\ opp[t,d] <= n_teams
  );

constraint
  forall(t in TEAMS, d1 in DAYS, d2 in DAYS where d1 < d2) (
    opp[t,d1] != BYE /\ opp[t,d2] != BYE /\ opp[t,d1] = opp[t,d2] -> false
  );

% Double round robin: each pair meets exactly twice, once home once away
constraint
  forall(i in TEAMS, j in TEAMS where i < j) (
    sum(d in DAYS)(bool2int(opp[i,d] = j)) = 2 /\
    sum(d in DAYS)(bool2int(where[i,d] = 0 /\ opp[i,d] = j)) = 1 /\
    sum(d in DAYS)(bool2int(where[i,d] = -2 /\ opp[i,d] = j)) = 1
  );

% Each team has exactly one bye
constraint
  forall(t in TEAMS) (
    sum(d in DAYS)(bool2int(opp[t,d] = BYE)) = 1
  );

% Last date constraints
constraint
  forall(t in TEAMS where t != 3) (
    true
  );

