constraint
  forall(i in TEAMS, j in TEAMS where i < j) (
    sum(d in DAYS)(bool2int(config[d,i] = j /\ where[d,i] = 0)) = 1 /\
    sum(d in DAYS)(bool2int(config[d,i] = j /\ where[d,i] = -2)) = 1 /\
