    sum(d in [2,4,6,8,10,12,14,16,18])(bool2int(where[d,i] = -2)) = 4 /\
    sum(d in [2,4,6,8,10,12,14,16,18])(bool2int(where[d,i] = -1)) = 1
  );

% First five weekends: at least two home or bye
constraint
  forall(i in TEAMS) (
    sum(d in [2,4,6,8,10])(bool2int(where[d,i] = 0 \/ where[d,i] = -1)) >= 2
  );

