  sum(d in 11..18)(bool2int((config[d,Wake] = Duke) \/ (config[d,Duke] = Wake))) >= 1 /\
  sum(d in 11..18)(bool2int((config[d,GT] = UNC) \/ (config[d,UNC] = GT))) >= 1 /\
  sum(d in 11..18)(bool2int((config[d,GT] = Duke) \/ (config[d,Duke] = GT))) >= 1;

