        (config[d,i] = UNC /\ config[d+1,i] = Wake /\ config[d+2,i] = Duke) \/
        (config[d,i] = Duke /\ config[d+1,i] = UNC /\ config[d+2,i] = Wake) \/
        (config[d,i] = Duke /\ config[d+1,i] = Wake /\ config[d+2,i] = UNC) \/
        (config[d,i] = Wake /\ config[d+1,i] = UNC /\ config[d+2,i] = Duke) \/
        (config[d,i] = Wake /\ config[d+1,i] = Duke /\ config[d+2,i] = UNC))
  );

% Other constraints
constraint config[11,UNC] = Duke /\ config[11,Duke] = UNC;
constraint config[2,UNC] = Clem /\ config[2,Clem] = UNC;
constraint where[16,Duke] = -1;
constraint where[17,Wake] != 0;
constraint where[1,Wake] = -1;
constraint where[18,Clem] != -2 /\ where[18,Duke] != -2 /\ where[18,UMD] != -2 /\ where[18,Wake] != -2;
constraint where[1,Clem] != -2 /\ where[1,FSU] != -2 /\ where[1,GT] != -2 /\ where[1,Wake] != -2;
constraint where[18,FSU] != -1 /\ where[18,NCSt] != -1;
constraint where[1,UNC] != -1;

solve satisfy;

output [
  "{",
  "\"config\":", show(config), ",",
  "\"where\":", show(where),
  "}"
