% Strategy: dual viewpoint using exact per-line regular-language-style block placement with reified start positions and channeling to cell variables; corrected to preserve all feasible boards.
int: rows;
int: cols;
int: row_rule_len;
int: col_rule_len;

array[1..rows, 1..row_rule_len] of int: row_rules;
array[1..cols, 1..col_rule_len] of int: col_rules;

array[1..rows, 1..cols] of var 0..1: board;

function int: nblocks(array[int] of int: rules) =
    sum(i in index_set(rules))(bool2int(rules[i] > 0));

function int: total_len(array[int] of int: rules) =
    sum(i in index_set(rules))(rules[i]);

predicate line_matches(array[int] of var 0..1: line, array[int] of int: rules) =
    let {
        int: n = length(line),
        int: m = max(index_set(rules)),
        array[1..m] of var 1..n: start,
        array[1..m] of var bool: active,
        array[1..m] of int: min_start = [1 + sum(j in 1..k-1)(rules[j]) + sum(j in 1..k-1)(bool2int(rules[j] > 0)) | k in 1..m],
        array[1..m] of int: max_start = [n - sum(j in k+1..m)(rules[j]) - sum(j in k+1..m)(bool2int(rules[j] > 0)) - rules[k] + 1 | k in 1..m]
    } in
    (
        forall(k in 1..m)(
            active[k] <-> (rules[k] > 0)
        )
        /\
        forall(k in 1..m)(
            active[k] -> (start[k] >= min_start[k] /\ start[k] <= max_start[k])
        )
        /\
        forall(k in 1..m)(
            not active[k] -> start[k] = 1
        )
        /\
        forall(k in 1..m-1)(
            active[k] /\ active[k+1] -> start[k+1] >= start[k] + rules[k] + 1
        )
        /\
        forall(i in 1..n)(
            line[i] = bool2int(
                exists(k in 1..m)(
                    active[k] /\ i >= start[k] /\ i < start[k] + rules[k]
                )
            )
        )
    );

constraint forall(r in 1..rows)(
    line_matches([board[r,c] | c in 1..cols], row_rules[r,1..row_rule_len])
);

constraint forall(c in 1..cols)(
    line_matches([board[r,c] | r in 1..rows], col_rules[c,1..col_rule_len])
);

solve satisfy;

output ["{\"board\":", show([ [board[r,c] | c in 1..cols] | r in 1..rows ]), "}"];

