from pycsp3 import *

# Strategy: explicit sequence-automaton reformulation.
# Each row/column is modeled as a 0/1 line constrained by a regular-language automaton built from its clues.

board = VarArray(size=[rows, cols], dom={0, 1})

def clues(rule):
    return [x for x in rule if x > 0]

def line_matches_clue(line, clue):
    # Enumerate all valid 0/1 patterns for one line of given length and clue.
    length = len(line)
    blocks = clues(clue)

    patterns = []

    def rec(prefix, idx, started):
        if idx == length:
            # Accept iff all blocks have been placed and we are not in the middle of a block.
            if started == len(blocks):
                patterns.append(prefix[:])
            return

        if started == len(blocks):
            # No more blocks: rest must be zeros
            patterns.append(prefix + [0] * (length - idx))
            return

        b = blocks[started]

        # Option 1: put a 0, if this does not violate required placement
        # Zeros can appear before blocks, between blocks, or after all blocks.
        prefix.append(0)
        rec(prefix, idx + 1, started)
        prefix.pop()

        # Option 2: start/continue a block when possible
        # We build valid patterns by direct enumeration of block placements.
        # This branch is only used via a dedicated generator below.
        return

    # Direct generation of patterns by choosing gaps between blocks.
    if not blocks:
        patterns = [[0] * length]
    else:
        k = len(blocks)

        def gen(gaps, pos, bi):
            if bi == k:
                # trailing zeros
                tail = length - pos
                if tail >= 0:
                    pat = [0] * gaps[0]
                    p = gaps[0]
                    for i, bl in enumerate(blocks):
                        pat += [1] * bl
                        p += bl
                        if i < k - 1:
                            pat += [0] * (1 + gaps[i + 1])
                            p += 1 + gaps[i + 1]
                    pat += [0] * (length - len(pat))
                    if len(pat) == length:
                        patterns.append(pat)
                return

        # Use compositions of the extra zeros across k+1 gaps.
        min_len = sum(blocks) + (k - 1)
        extra = length - min_len
        if extra >= 0:
            def comp(rem, parts, acc):
                if parts == 1:
                    yield acc + [rem]
                else:
                    for x in range(rem + 1):
                        yield from comp(rem - x, parts - 1, acc + [x])

            for gaps in comp(extra, k + 1, []):
                pat = [0] * gaps[0]
                for i, bl in enumerate(blocks):
                    pat += [1] * bl
                    if i < k - 1:
                        pat += [0] * (1 + gaps[i + 1])
                pat += [0] * gaps[-1]
                if len(pat) == length:
                    patterns.append(pat)

    # Remove duplicates just in case
    patterns = [list(p) for p in dict.fromkeys(tuple(p) for p in patterns)]

    satisfy(Or(*[
        And(*[line[i] == pat[i] for i in range(length)])
        for pat in patterns
    ]))

