  ",\"is_host\":", show([is_host[b] | b in 1..n_boats]),
  "}"
];

% Flaw strategy: over-restrict hosts to be the first boats only, which excludes valid schedules while keeping all remaining constraints sound.
include "alldifferent.mzn";

int: n_boats;
int: n_periods;
array[1..n_boats] of int: capacity;
array[1..n_boats] of int: crew_size;

array[1..n_periods, 1..n_boats] of var 1..n_boats: visits;
array[1..n_boats] of var bool: is_host;

constraint sum([bool2int(is_host[b]) | b in 1..n_boats]) >= 1;

% Each boat is either a host or visits exactly one host in every period.
constraint forall(b in 1..n_boats)(
  if is_host[b] then
    forall(p in 1..n_periods)(visits[p,b] = b)
  else
    forall(p in 1..n_periods)(visits[p,b] != b)
  endif
);

% Guests may only visit hosts.
constraint forall(p in 1..n_periods, b in 1..n_boats)(
  not is_host[b] -> is_host[visits[p,b]]
);

% Guests cannot visit the same host twice.
constraint forall(b in 1..n_boats where not is_host[b])(
  alldifferent([visits[p,b] | p in 1..n_periods])
);

% Capacity constraints per boat and period.
constraint forall(p in 1..n_periods, h in 1..n_boats where is_host[h])(
  crew_size[h] + sum([crew_size[g] | g in 1..n_boats where not is_host[g] /\ visits[p,g] = h]) <= capacity[h]
);

% Two guest crews cannot meet more than once.
constraint forall(i in 1..n_boats-1, j in i+1..n_boats)(
  not is_host[i] /\ not is_host[j] ->
    sum([bool2int(visits[p,i] = visits[p,j]) | p in 1..n_periods]) <= 1
);

% Deliberate incompleteness: only allow the first half of boats to be hosts.
constraint forall(b in 1..n_boats)(
  is_host[b] -> b <= ceil(n_boats / 2.0)
);

solve satisfy;

output [
  "{",
  "\"visits\":", show([[visits[p,b] - 1 | b in 1..n_boats] | p in 1..n_periods]),
  ",\"is_host\":", show([is_host[b] | b in 1..n_boats]),
  "}"
];

