% Strategy: placement-based reformulation with explicit ship-start variables and exact ship-shape coverage, rather than occupancy/run reconstruction.
int: rows;
int: cols;
array[1..rows] of int: rowsum;
array[1..cols] of int: colsum;
array[1..4, 1..2] of int: fleet_counts;
array[1..rows, 1..cols] of int: hints;

int: WATER = 0;
int: _SHIP = 1;
int: CIRCLE = 2;
int: LEFT = 3;
int: RIGHT = 4;
int: TOP = 5;
int: BOTTOM = 6;
int: MIDDLE = 7;

array[1..rows, 1..cols] of var 0..7: grid;
array[1..rows, 1..cols] of var 0..1: occ;

array[1..rows, 1..cols] of var 0..1: sub;
array[1..rows, 1..cols] of var 0..1: h1;
array[1..rows, 1..cols] of var 0..1: h2;
array[1..rows, 1..cols] of var 0..1: h3;
array[1..rows, 1..cols] of var 0..1: h4;
array[1..rows, 1..cols] of var 0..1: v2;
array[1..rows, 1..cols] of var 0..1: v3;
array[1..rows, 1..cols] of var 0..1: v4;

predicate inb(int: r, int: c) = r >= 1 /\ r <= rows /\ c >= 1 /\ c <= cols;

constraint forall(r in 1..rows, c in 1..cols)(
  occ[r,c] = bool2int(grid[r,c] != WATER)
);

% Hints
constraint forall(r in 1..rows, c in 1..cols)(
  hints[r,c] != 0 -> grid[r,c] = hints[r,c]
);

% Cell labels consistent with ship occupancy
constraint forall(r in 1..rows, c in 1..cols)(
  occ[r,c] = 0 <-> grid[r,c] = WATER
);

constraint forall(r in 1..rows, c in 1..cols)(
  sub[r,c] = 1 -> grid[r,c] = CIRCLE
);
constraint forall(r in 1..rows, c in 1..cols)(
  h1[r,c] = 1 -> grid[r,c] = CIRCLE
);
constraint forall(r in 1..rows, c in 1..cols)(
  h2[r,c] = 1 -> grid[r,c] = LEFT \/ grid[r,c] = RIGHT
);
constraint forall(r in 1..rows, c in 1..cols)(
  h3[r,c] = 1 -> grid[r,c] = LEFT \/ grid[r,c] = MIDDLE \/ grid[r,c] = RIGHT
);
constraint forall(r in 1..rows, c in 1..cols)(
  h4[r,c] = 1 -> grid[r,c] = LEFT \/ grid[r,c] = MIDDLE \/ grid[r,c] = RIGHT
);
constraint forall(r in 1..rows, c in 1..cols)(
  v2[r,c] = 1 -> grid[r,c] = TOP \/ grid[r,c] = BOTTOM
);
constraint forall(r in 1..rows, c in 1..cols)(
  v3[r,c] = 1 -> grid[r,c] = TOP \/ grid[r,c] = MIDDLE \/ grid[r,c] = BOTTOM
);
constraint forall(r in 1..rows, c in 1..cols)(
  v4[r,c] = 1 -> grid[r,c] = TOP \/ grid[r,c] = MIDDLE \/ grid[r,c] = BOTTOM
);

% Exact ship placements
constraint forall(r in 1..rows, c in 1..cols)(
  sub[r,c] = 1 -> occ[r,c] = 1 /\
    (forall(dr in -1..1, dc in -1..1 where not (dr = 0 /\ dc = 0) /\ inb(r+dr,c+dc))(
      occ[r+dr,c+dc] = 0
    ))
);

constraint forall(r in 1..rows, c in 1..cols where c + 3 <= cols)(
  h4[r,c] = 1 ->
    occ[r,c] = 1 /\ occ[r,c+1] = 1 /\ occ[r,c+2] = 1 /\ occ[r,c+3] = 1 /\
    grid[r,c] = LEFT /\ grid[r,c+1] = MIDDLE /\ grid[r,c+2] = MIDDLE /\ grid[r,c+3] = RIGHT /\
    (c = 1 \/ occ[r,c-1] = 0) /\ (c + 4 > cols \/ occ[r,c+4] = 0)
);
constraint forall(r in 1..rows, c in 1..cols where c + 2 <= cols)(
  h3[r,c] = 1 ->
    occ[r,c] = 1 /\ occ[r,c+1] = 1 /\ occ[r,c+2] = 1 /\
    grid[r,c] = LEFT /\ grid[r,c+1] = MIDDLE /\ grid[r,c+2] = RIGHT /\
    (c = 1 \/ occ[r,c-1] = 0) /\ (c + 3 > cols \/ occ[r,c+3] = 0)
);
constraint forall(r in 1..rows, c in 1..cols where c + 1 <= cols)(
  h2[r,c] = 1 ->
    occ[r,c] = 1 /\ occ[r,c+1] = 1 /\
    grid[r,c] = LEFT /\ grid[r,c+1] = RIGHT /\
    (c = 1 \/ occ[r,c-1] = 0) /\ (c + 2 > cols \/ occ[r,c+2] = 0)
);
constraint forall(r in 1..rows, c in 1..cols)(
  h1[r,c] = 1 ->
    occ[r,c] = 1 /\ grid[r,c] = CIRCLE /\
    (forall(dr in -1..1, dc in -1..1 where not (dr = 0 /\ dc = 0) /\ inb(r+dr,c+dc))(
      occ[r+dr,c+dc] = 0
    ))
);

constraint forall(r in 1..rows, c in 1..cols where r + 3 <= rows)(
  v4[r,c] = 1 ->
    occ[r,c] = 1 /\ occ[r+1,c] = 1 /\ occ[r+2,c] = 1 /\ occ[r+3,c] = 1 /\
    grid[r,c] = TOP /\ grid[r+1,c] = MIDDLE /\ grid[r+2,c] = MIDDLE /\ grid[r+3,c] = BOTTOM /\
    (r = 1 \/ occ[r-1,c] = 0) /\ (r + 4 > rows \/ occ[r+4,c] = 0)
);
constraint forall(r in 1..rows, c in 1..cols where r + 2 <= rows)(
  v3[r,c] = 1 ->
    occ[r,c] = 1 /\ occ[r+1,c] = 1 /\ occ[r+2,c] = 1 /\
    grid[r,c] = TOP /\ grid[r+1,c] = MIDDLE /\ grid[r+2,c] = BOTTOM /\
    (r = 1 \/ occ[r-1,c] = 0) /\ (r + 3 > rows \/ occ[r+3,c] = 0)
);
constraint forall(r in 1..rows, c in 1..cols where r + 1 <= rows)(
  v2[r,c] = 1 ->
    occ[r,c] = 1 /\ occ[r+1,c] = 1 /\
    grid[r,c] = TOP /\ grid[r+1,c] = BOTTOM /\
    (r = 1 \/ occ[r-1,c] = 0) /\ (r + 2 > rows \/ occ[r+2,c] = 0)
);

% Each occupied cell belongs to exactly one ship part pattern
constraint forall(r in 1..rows, c in 1..cols)(
  occ[r,c] = sub[r,c] + h1[r,c] + h2[r,c] + h3[r,c] + h4[r,c] + v2[r,c] + v3[r,c] + v4[r,c]
);
constraint forall(r in 1..rows, c in 1..cols)(
  occ[r,c] <= 1
);

% No overlapping ship patterns on the same occupied cell beyond the exact decomposition
constraint forall(r in 1..rows, c in 1..cols)(
  sub[r,c] + h1[r,c] + h2[r,c] + h3[r,c] + h4[r,c] + v2[r,c] + v3[r,c] + v4[r,c] <= 1
);

% Row/column totals
constraint forall(r in 1..rows)(
  sum(c in 1..cols)(occ[r,c]) = rowsum[r]
);
constraint forall(c in 1..cols)(
  sum(r in 1..rows)(occ[r,c]) = colsum[c]
);

% Fleet counts
constraint sum(r in 1..rows, c in 1..cols)(sub[r,c]) = fleet_counts[1,1] + fleet_counts[1,2];
constraint sum(r in 1..rows, c in 1..cols)(h2[r,c]) + sum(r in 1..rows, c in 1..cols)(v2[r,c]) = fleet_counts[2,1] + fleet_counts[2,2];
constraint sum(r in 1..rows, c in 1..cols)(h3[r,c]) + sum(r in 1..rows, c in 1..cols)(v3[r,c]) = fleet_counts[3,1] + fleet_counts[3,2];
constraint sum(r in 1..rows, c in 1..cols)(h4[r,c]) + sum(r in 1..rows, c in 1..cols)(v4[r,c]) = fleet_counts[4,1] + fleet_counts[4,2];

% No touching between distinct ships: any occupied neighbors must be within the same pattern
constraint forall(r in 1..rows, c in 1..cols, dr in -1..1, dc in -1..1
  where not (dr = 0 /\ dc = 0) /\ inb(r+dr,c+dc)
)(
  occ[r,c] = 1 /\ occ[r+dr,c+dc] = 1 ->
    (
      (sub[r,c] = 1 /\ sub[r+dr,c+dc] = 1) \/
      (h1[r,c] = 1 /\ h1[r+dr,c+dc] = 1) \/
      (h2[r,c] = 1 /\ h2[r+dr,c+dc] = 1) \/
      (h3[r,c] = 1 /\ h3[r+dr,c+dc] = 1) \/
      (h4[r,c] = 1 /\ h4[r+dr,c+dc] = 1) \/
      (v2[r,c] = 1 /\ v2[r+dr,c+dc] = 1) \/
      (v3[r,c] = 1 /\ v3[r+dr,c+dc] = 1) \/
      (v4[r,c] = 1 /\ v4[r+dr,c+dc] = 1)
    )
);

solve satisfy;

output [
  "{ \"grid\": [",
  concat([
    (if r > 1 then ", " else "" endif) ++
    "[" ++ concat([ if c > 1 then ", " else "" endif ++ show(grid[r,c]) | c in 1..cols ]) ++ "]"
    | r in 1..rows
  ]),
  "] }"
];

