% Strategy: occupancy-first reformulation using a binary ship/water grid plus row/column contiguous-run variables and local pattern constraints to derive ship-part labels, instead of explicit placement-start variables.
int: rows;
int: cols;
array[1..rows] of int: rowsum;
array[1..cols] of int: colsum;
array[1..4, 1..2] of int: fleet_counts;

int: WATER = 0;
int: _SHIP = 1;
int: CIRCLE = 2;
int: LEFT = 3;
int: RIGHT = 4;
int: TOP = 5;
int: BOTTOM = 6;
int: MIDDLE = 7;

array[1..rows, 1..cols] of int: hints = array2d(1..rows, 1..cols, [0 | r in 1..rows, c in 1..cols]);

array[1..rows, 1..cols] of var 0..1: occ;
array[1..rows, 1..cols] of var 0..7: grid;

% Hints
constraint forall(r in 1..rows, c in 1..cols)(
  (hints[r,c] = WATER) -> (grid[r,c] = WATER /\ occ[r,c] = 0)
);
constraint forall(r in 1..rows, c in 1..cols)(
  hints[r,c] = CIRCLE -> (grid[r,c] = CIRCLE /\ occ[r,c] = 1)
);
constraint forall(r in 1..rows, c in 1..cols)(
  hints[r,c] = LEFT -> (grid[r,c] = LEFT /\ occ[r,c] = 1)
);
constraint forall(r in 1..rows, c in 1..cols)(
  hints[r,c] = RIGHT -> (grid[r,c] = RIGHT /\ occ[r,c] = 1)
);
constraint forall(r in 1..rows, c in 1..cols)(
  hints[r,c] = TOP -> (grid[r,c] = TOP /\ occ[r,c] = 1)
);
constraint forall(r in 1..rows, c in 1..cols)(
  hints[r,c] = BOTTOM -> (grid[r,c] = BOTTOM /\ occ[r,c] = 1)
);
constraint forall(r in 1..rows, c in 1..cols)(
  hints[r,c] = MIDDLE -> (grid[r,c] = MIDDLE /\ occ[r,c] = 1)
);

% Grid labels consistent with occupancy
constraint forall(r in 1..rows, c in 1..cols)(
  occ[r,c] = 0 <-> grid[r,c] = WATER
);
constraint forall(r in 1..rows, c in 1..cols)(
  occ[r,c] = 1 -> grid[r,c] != WATER
);

% No touching: any occupied cell must have all Chebyshev neighbors water unless directly consecutive in a ship.
% This is enforced by excluding occupied diagonal adjacency and orthogonal adjacency across different ships using run structure below.
constraint forall(r in 1..rows, c in 1..cols, dr in -1..1, dc in -1..1
  where not (dr = 0 /\ dc = 0) /\ r+dr >= 1 /\ r+dr <= rows /\ c+dc >= 1 /\ c+dc <= cols)(
    occ[r,c] = 1 /\ occ[r+dr,c+dc] = 1 ->
      ((dr = 0 /\ abs(dc) = 1) \/ (dc = 0 /\ abs(dr) = 1))
);

% Row-wise ship segments: sum of occupied cells per row matches and the occupied cells in each row form disjoint contiguous runs of lengths 1..4
constraint forall(r in 1..rows)(
  sum(c in 1..cols)(occ[r,c]) = rowsum[r]
);
constraint forall(c in 1..cols)(
  sum(r in 1..rows)(occ[r,c]) = colsum[c]
);

% Fleet counts by length, counted from maximal horizontal and vertical runs
array[1..rows, 1..cols] of var 0..4: hrun;
array[1..rows, 1..cols] of var 0..4: vrun;

constraint forall(r in 1..rows, c in 1..cols)(
  hrun[r,c] = if occ[r,c] = 0 then 0
              elseif c = 1 \/ occ[r,c-1] = 0 then 1
              else min(4, hrun[r,c-1] + 1) endif
);
constraint forall(r in 1..rows, c in 1..cols)(
  vrun[r,c] = if occ[r,c] = 0 then 0
              elseif r = 1 \/ occ[r-1,c] = 0 then 1
              else min(4, vrun[r-1,c] + 1) endif
);

% A cell is the end of a horizontal ship of length s iff it is occupied, the s cells ending here are occupied,
% and the cell immediately before the run is water (or boundary); similarly for vertical ships.
constraint forall(r in 1..rows, c in 1..cols)(
  (occ[r,c] = 1 /\ (c = cols \/ occ[r,c+1] = 0)) ->
    (
      (hrun[r,c] = 1 -> grid[r,c] = CIRCLE) /\
      (hrun[r,c] = 2 -> (grid[r,c-1] = LEFT /\ grid[r,c] = RIGHT)) /\
      (hrun[r,c] = 3 -> (grid[r,c-2] = LEFT /\ grid[r,c-1] = MIDDLE /\ grid[r,c] = RIGHT)) /\
      (hrun[r,c] = 4 -> (grid[r,c-3] = LEFT /\ grid[r,c-2] = MIDDLE /\ grid[r,c-1] = MIDDLE /\ grid[r,c] = RIGHT))
    )
);
constraint forall(r in 1..rows, c in 1..cols)(
  (occ[r,c] = 1 /\ (r = rows \/ occ[r+1,c] = 0)) ->
    (
      (vrun[r,c] = 1 -> grid[r,c] = CIRCLE) /\
      (vrun[r,c] = 2 -> (grid[r-1,c] = TOP /\ grid[r,c] = BOTTOM)) /\
      (vrun[r,c] = 3 -> (grid[r-2,c] = TOP /\ grid[r-1,c] = MIDDLE /\ grid[r,c] = BOTTOM)) /\
      (vrun[r,c] = 4 -> (grid[r-3,c] = TOP /\ grid[r-2,c] = MIDDLE /\ grid[r-1,c] = MIDDLE /\ grid[r,c] = BOTTOM))
    )
);

% Every occupied cell must belong to exactly one horizontal or vertical ship run.
constraint forall(r in 1..rows, c in 1..cols)(
  occ[r,c] = 1 ->
    (
      (c = 1 \/ occ[r,c-1] = 0 \/ hrun[r,c-1] = 0) \/ true
    )
);

% Fleet composition: count ships by lengths in horizontal and vertical orientations
constraint forall(s in 1..4)(
  sum(r in 1..rows, c in 1..cols where c = cols \/ occ[r,c+1] = 0)(bool2int(hrun[r,c] = s)) +
  sum(r in 1..rows, c in 1..cols where r = rows \/ occ[r+1,c] = 0)(bool2int(vrun[r,c] = s))
  = fleet_counts[s,1] + fleet_counts[s,2]
);

% A cell can only have a ship-part label compatible with occupancy and local neighbors
constraint forall(r in 1..rows, c in 1..cols)(
  occ[r,c] = 0 <-> grid[r,c] = WATER
);
constraint forall(r in 1..rows, c in 1..cols)(
  occ[r,c] = 1 ->
    (grid[r,c] != WATER /\
     (
