      occ[r+dr,c+dc] = 0
    ))
);

constraint forall(r in 1..rows, c in 1..cols where r + 3 <= rows)(
  v4[r,c] = 1 ->
    occ[r,c] = 1 /\ occ[r+1,c] = 1 /\ occ[r+2,c] = 1 /\ occ[r+3,c] = 1 /\
    grid[r,c] = TOP /\ grid[r+1,c] = MIDDLE /\ grid[r+2,c] = MIDDLE /\ grid[r+3,c] = BOTTOM /\
    (r = 1 \/ occ[r-1,c] = 0) /\ (r + 4 > rows \/ occ[r+4,c] = 0)
);
constraint forall(r in 1..rows, c in 1..cols where r + 2 <= rows)(
  v3[r,c] = 1 ->
    occ[r,c] = 1 /\ occ[r+1,c] = 1 /\ occ[r+2,c] = 1 /\
    grid[r,c] = TOP /\ grid[r+1,c] = MIDDLE /\ grid[r+2,c] = BOTTOM /\
    (r = 1 \/ occ[r-1,c] = 0) /\ (r + 3 > rows \/ occ[r+3,c] = 0)
);
constraint forall(r in 1..rows, c in 1..cols where r + 1 <= rows)(
  v2[r,c] = 1 ->
    occ[r,c] = 1 /\ occ[r+1,c] = 1 /\
    grid[r,c] = TOP /\ grid[r+1,c] = BOTTOM /\
    (r = 1 \/ occ[r-1,c] = 0) /\ (r + 2 > rows \/ occ[r+2,c] = 0)
);

% Each occupied cell belongs to exactly one ship part pattern
constraint forall(r in 1..rows, c in 1..cols)(
  occ[r,c] = sub[r,c] + h1[r,c] + h2[r,c] + h3[r,c] + h4[r,c] + v2[r,c] + v3[r,c] + v4[r,c]
);
constraint forall(r in 1..rows, c in 1..cols)(
  occ[r,c] <= 1
);

% No overlapping ship patterns on the same occupied cell beyond the exact decomposition
constraint forall(r in 1..rows, c in 1..cols)(
  sub[r,c] + h1[r,c] + h2[r,c] + h3[r,c] + h4[r,c] + v2[r,c] + v3[r,c] + v4[r,c] <= 1
);

% Row/column totals
constraint forall(r in 1..rows)(
  sum(c in 1..cols)(occ[r,c]) = rowsum[r]
);
constraint forall(c in 1..cols)(
  sum(r in 1..rows)(occ[r,c]) = colsum[c]
);

% Fleet counts
constraint sum(r in 1..rows, c in 1..cols)(sub[r,c]) = fleet_counts[1,1] + fleet_counts[1,2];
constraint sum(r in 1..rows, c in 1..cols)(h2[r,c]) + sum(r in 1..rows, c in 1..cols)(v2[r,c]) = fleet_counts[2,1] + fleet_counts[2,2];
constraint sum(r in 1..rows, c in 1..cols)(h3[r,c]) + sum(r in 1..rows, c in 1..cols)(v3[r,c]) = fleet_counts[3,1] + fleet_counts[3,2];
constraint sum(r in 1..rows, c in 1..cols)(h4[r,c]) + sum(r in 1..rows, c in 1..cols)(v4[r,c]) = fleet_counts[4,1] + fleet_counts[4,2];

