      (h1[r,c] = 1 /\ h1[r+dr,c+dc] = 1) \/
      (h2[r,c] = 1 /\ h2[r+dr,c+dc] = 1) \/
      (h3[r,c] = 1 /\ h3[r+dr,c+dc] = 1) \/
      (h4[r,c] = 1 /\ h4[r+dr,c+dc] = 1) \/
      (v2[r,c] = 1 /\ v2[r+dr,c+dc] = 1) \/
      (v3[r,c] = 1 /\ v3[r+dr,c+dc] = 1) \/
      (v4[r,c] = 1 /\ v4[r+dr,c+dc] = 1)
    )
);

solve satisfy;

