from pycsp3 import *

# Strategy: dual cell-centric model with ship-type variables per cell, exact row/column sums, local adjacency bans, and global fleet counting by extracted ship cells.

nrows, ncols = rows, cols

# Cell types:
# 0 water, 1 ship cell (generic), 2 submarine, 3 left, 4 right, 5 top, 6 bottom, 7 middle
grid = VarArray(size=[nrows, ncols], dom=range(8))

# Helper booleans for cell categories
is_water = VarArray(size=[nrows, ncols], dom={0, 1})
is_ship = VarArray(size=[nrows, ncols], dom={0, 1})

# Orientation/part indicators per cell
is_sub = VarArray(size=[nrows, ncols], dom={0, 1})
is_left = VarArray(size=[nrows, ncols], dom={0, 1})
is_right = VarArray(size=[nrows, ncols], dom={0, 1})
is_top = VarArray(size=[nrows, ncols], dom={0, 1})
is_bottom = VarArray(size=[nrows, ncols], dom={0, 1})
is_middle = VarArray(size=[nrows, ncols], dom={0, 1})

def in_grid(i, j):
    return 0 <= i < nrows and 0 <= j < ncols

satisfy(
    # Initial hints
    [grid[r][c] == v for r, c, v in hints],

    # Channel cell value to part indicators
    [
        is_water[r][c] == (grid[r][c] == WATER) for r in range(nrows) for c in range(ncols)
    ],
    [
        is_ship[r][c] == (grid[r][c] != WATER) for r in range(nrows) for c in range(ncols)
    ],
    [
        is_sub[r][c] == (grid[r][c] == CIRCLE) for r in range(nrows) for c in range(ncols)
    ],
    [
        is_left[r][c] == (grid[r][c] == LEFT) for r in range(nrows) for c in range(ncols)
    ],
    [
        is_right[r][c] == (grid[r][c] == RIGHT) for r in range(nrows) for c in range(ncols)
    ],
    [
        is_top[r][c] == (grid[r][c] == TOP) for r in range(nrows) for c in range(ncols)
    ],
    [
        is_bottom[r][c] == (grid[r][c] == BOTTOM) for r in range(nrows) for c in range(ncols)
    ],
    [
        is_middle[r][c] == (grid[r][c] == MIDDLE) for r in range(nrows) for c in range(ncols)
    ],

    # Each cell has exactly one status
    [
        is_water[r][c] + is_sub[r][c] + is_left[r][c] + is_right[r][c] + is_top[r][c] + is_bottom[r][c] + is_middle[r][c] == 1
        for r in range(nrows) for c in range(ncols)
    ],

    # Row/column totals count occupied cells
    [Sum(is_ship[r][c] for c in range(ncols)) == rowsum[r] for r in range(nrows)],
    [Sum(is_ship[r][c] for r in range(nrows)) == colsum[c] for c in range(ncols)],

    # Local consistency of ship parts
    [
        is_sub[r][c] <= 1
        for r in range(nrows) for c in range(ncols)
    ],
    [
        is_left[r][c] <= (is_ship[r][c] and (c + 1 < ncols))
        for r in range(nrows) for c in range(ncols)
    ],

    # Shape rules for each part type
    [
        is_sub[r][c] == (
            (grid[r][c] == CIRCLE)
        )
        for r in range(nrows) for c in range(ncols)
    ],
    [
        is_left[r][c] -> (c + 1 < ncols and is_ship[r][c + 1] and (grid[r][c + 1] in [RIGHT, MIDDLE]))
        for r in range(nrows) for c in range(ncols)
    ],
    [
        is_right[r][c] -> (c - 1 >= 0 and is_ship[r][c - 1] and (grid[r][c - 1] in [LEFT, MIDDLE]))
        for r in range(nrows) for c in range(ncols)
    ],
    [
        is_top[r][c] -> (r + 1 < nrows and is_ship[r + 1][c] and (grid[r + 1][c] in [BOTTOM, MIDDLE]))
        for r in range(nrows) for c in range(ncols)
    ],
    [
        is_bottom[r][c] -> (r - 1 >= 0 and is_ship[r - 1][c] and (grid[r - 1][c] in [TOP, MIDDLE]))
        for r in range(nrows) for c in range(ncols)
    ],
    [
        is_middle[r][c] -> (
            (
                (r - 1 >= 0 and is_ship[r - 1][c]) +
                (r + 1 < nrows and is_ship[r + 1][c]) +
                (c - 1 >= 0 and is_ship[r][c - 1]) +
                (c + 1 < ncols and is_ship[r][c + 1])
            ) == 2
        )
        for r in range(nrows) for c in range(ncols)
    ],

    # No adjacency between distinct ships: any occupied cell forbids surrounding occupied cells except along its own ship
    [
        is_ship[r][c] + is_ship[rr][cc] <= 1
        for r in range(nrows) for c in range(ncols)
        for rr in range(max(0, r - 1), min(nrows, r + 2))
        for cc in range(max(0, c - 1), min(ncols, c + 2))
        if not (rr == r and cc == c)
        if abs(rr - r) + abs(cc - c) != 1 or True
    ],

    # Fleet counting by ship starts:
    # submarine cell itself is a ship of size 1
    Sum(is_sub[r][c] for r in range(nrows) for c in range(ncols)) == fleet_counts[3][1],

    # Horizontal ships: left endpoints define length 2,3,4
    Sum((is_left[r][c] & (c + 1 < ncols) & is_right[r][c + 1]) for r in range(nrows) for c in range(ncols)) == fleet_counts[2][1],
    Sum((is_left[r][c] & (c + 2 < ncols) & is_middle[r][c + 1] & is_right[r][c + 2]) for r in range(nrows) for c in range(ncols)) == fleet_counts[1][1],
    Sum((is_left[r][c] & (c + 3 < ncols) & is_middle[r][c + 1] & is_middle[r][c + 2] & is_right[r][c + 3]) for r in range(nrows) for c in range(ncols)) == fleet_counts[0][1],

    # Vertical ships: top endpoints define length 2,3,4
    Sum((is_top[r][c] & (r + 1 < nrows) & is_bottom[r + 1][c]) for r in range(nrows) for c in range(ncols)) == fleet_counts[2][1],
    Sum((is_top[r][c] & (r + 2 < nrows) & is_middle[r + 1][c] & is_bottom[r + 2][c]) for r in range(nrows) for c in range(ncols)) == fleet_counts[1][1],
    Sum((is_top[r][c] & (r + 3 < nrows) & is_middle[r + 1][c] & is_middle[r + 2][c] & is_bottom[r + 3][c]) for r in range(nrows) for c in range(ncols)) == fleet_counts[0][1],

    # Each ship cell must belong to exactly one ship pattern: either submarine, horizontal, or vertical segment
    [
        is_ship[r][c] == (
            is_sub[r][c] + is_left[r][c] + is_right[r][c] + is_top[r][c] + is_bottom[r][c] + is_middle[r][c]
        )
        for r in range(nrows) for c in range(ncols)
    ]
)

# Unsoundness: omit diagonal-adjacency enforcement around prefilled ship hints, which can admit invalid touching configurations while keeping all row/column and fleet constraints intact.
from pycsp3 import *

WATER = 0
_SUB = 1
LEFT = 3
RIGHT = 4
TOP = 5
BOTTOM = 6
MIDDLE = 7
CIRCLE = 2

ship_values = [CIRCLE, LEFT, RIGHT, TOP, BOTTOM, MIDDLE]

grid = VarArray(size=[rows, cols], dom=range(8))

# Cell domains: any clue cell is also a ship-related value, otherwise water or ship-related
for i in range(rows):
    for j in range(cols):
        if [i, j] in hints:
            satisfy(grid[i][j] == hints[hints.index([i, j])][2])
        else:
            satisfy(grid[i][j] in [WATER, _SUB, LEFT, RIGHT, TOP, BOTTOM, MIDDLE])

# Row/column sums count occupied ship squares
satisfy(
    [Sum([grid[i][j] != WATER for j in range(cols)]) == rowsum[i] for i in range(rows)],
    [Sum([grid[i][j] != WATER for i in range(rows)]) == colsum[j] for j in range(cols)]
)

# Fleet counts
satisfy(
    Count(grid, value=CIRCLE) == fleet_counts[3][1],
    Count(grid, value=LEFT) == fleet_counts[0][1],
    Count(grid, value=RIGHT) == fleet_counts[0][1],
    Count(grid, value=TOP) == fleet_counts[0][1],
    Count(grid, value=BOTTOM) == fleet_counts[0][1],
    Count(grid, value=MIDDLE) == fleet_counts[1][1]
)

# Local ship-shape consistency
for i in range(rows):
    for j in range(cols):
        if i == 0:
            if j == 0:
                pass
        if grid[i][j] == CIRCLE:
            satisfy(
                (i == 0 or grid[i-1][j] == WATER) | (i == rows-1 or grid[i+1][j] == WATER) |
                (j == 0 or grid[i][j-1] == WATER) | (j == cols-1 or grid[i][j+1] == WATER)
            )

for i in range(rows):
    for j in range(cols):
        if grid[i][j] == LEFT:
            satisfy(j < cols - 1)
        if grid[i][j] == RIGHT:
            satisfy(j > 0)
        if grid[i][j] == TOP:
            satisfy(i < rows - 1)
        if grid[i][j] == BOTTOM:
            satisfy(i > 0)

# Shape continuity implications
for i in range(rows):
    for j in range(cols):
        if i > 0:
            satisfy((grid[i][j] == TOP) >> (grid[i+1][j] in [MIDDLE, BOTTOM] if i < rows - 1 else False))
        if i < rows - 1:
            satisfy((grid[i][j] == BOTTOM) >> (grid[i-1][j] in [MIDDLE, TOP] if i > 0 else False))
        if j > 0:
            satisfy((grid[i][j] == LEFT) >> (grid[i][j+1] in [MIDDLE, RIGHT] if j < cols - 1 else False))
        if j < cols - 1:
            satisfy((grid[i][j] == RIGHT) >> (grid[i][j-1] in [MIDDLE, LEFT] if j > 0 else False))

# No adjacent ship squares, except a deliberate omission of diagonal checks around hints
for i in range(rows):
    for j in range(cols):
        if i > 0:
