int: n;
int: m;
array[1..m, 1..2] of int: graph;

set of int: V = 1..n;
set of int: E = 1..m;
set of int: L = 0..m;

array[V] of var L: nodes;
array[E] of var 1..m: edges;

constraint all_different(nodes);
constraint all_different(edges);

% Every edge label equals the absolute difference of its endpoint node labels.
constraint
  forall(e in E) (
    let {
      int: u = graph[e,1],
      int: v = graph[e,2]
    } in
      edges[e] = abs(nodes[u] - nodes[v])
  );

% Edge labels must be exactly the q distinct values 1..m (since there are m edges and all edge labels are distinct, while 0 is impossible for an edge).
constraint all_different(edges);
constraint forall(e in E)(edges[e] >= 1 /\ edges[e] <= m);

solve satisfy;

output ["{\"nodes\":", show(nodes), ",\"edges\":", show(edges), "}"];

