% Structural strategy: use an inverse-permutation viewpoint; assign each label in 0..m to exactly one node, then derive node labels and edge labels via reified label-pair uniqueness and absolute-difference constraints.
include "alldifferent.mzn";

int: n;
int: m;
array[1..m, 1..2] of int: graph;

set of int: V = 1..n;
set of int: E = 1..m;
set of int: L = 0..m;

array[V] of var L: nodes;
array[E] of var 1..m: edges;

array[L] of var V: inv;

constraint all_different(nodes);
constraint forall(v in V) (nodes[v] != 0 \/ exists(e in E)(graph[e,1] = v \/ graph[e,2] = v));
constraint forall(l in L) (inv[l] in V);

constraint forall(v in V) (inv[nodes[v]] = v);
constraint forall(l in L) (nodes[inv[l]] = l);

constraint all_different(edges);
constraint forall(e in E) (
  let {
    int: u = graph[e,1],
    int: v = graph[e,2]
  } in
    edges[e] = abs(nodes[u] - nodes[v])
);

constraint all_different([edges[e] | e in E]);

solve satisfy;

output ["{\"nodes\":", show(nodes), ",\"edges\":", show(edges), "}"];

