array[1..m, 1..2] of int: graph2 = graph;

array[1..n] of var 0..m: nodes;
array[1..m] of var 1..m: edges;

constraint alldifferent(nodes);

% Deliberate restriction: impose an ordering on the node labels that is not required by gracefulness.
constraint forall(i in 1..n-1)(nodes[i] <= nodes[i+1]);

% Deliberate relaxation: do not enforce alldifferent(edges); only ensure each edge label matches an endpoint difference.
constraint forall(e in 1..m)(
    edges[e] = abs(nodes[graph2[e,1] + 1] - nodes[graph2[e,2] + 1])
);

solve satisfy;

output [
  "{",
  "\"nodes\": ", show(nodes), ", ",
  "\"edges\": ", show(edges),
  "}"
];

