# Strategy: structurally distinct dual encoding using node-to-ring assignments as the primary model, with total_adms derived from assignments; hard constraints only, no optimization.
import cpmpy as cp
import json
import numpy as np

model = cp.Model()

ring_config = cp.boolvar(shape=(r, n), name="ring_config")

for i in range(n):
    for j in range(i + 1, n):
        if demand[i][j] > 0:
            model += cp.sum(ring_config[:, i] & ring_config[:, j]) >= 1

for k in range(r):
    model += cp.sum(ring_config[k, :]) <= capacity_nodes[k]

total_adms = cp.sum(ring_config)

if model.solve():
    solution = {
        "ring_config": ring_config.value().tolist(),
        "total_adms": int(total_adms.value())
    }
    print(json.dumps(solution))
else:
    print("No solution found.")

