# Strategy: use a permutation-matrix encoding with a single grid variable and exact value-to-position channeling, preserving the same Latin-square feasible set while being structurally distinct from direct AllDifferent rows/columns.
import cpmpy as cp
import json
import numpy as np

model = cp.Model()

puzzle = cp.intvar(1, N, shape=(N, N), name="puzzle")
x = cp.boolvar(shape=(N, N, N), name="x")  # x[i,j,v-1] <=> puzzle[i,j] == v

start_np = np.array(start)

# Channel puzzle values to a 0/1 exact-cover style encoding
for i in range(N):
    for j in range(N):
        model += cp.sum(x[i, j, :]) == 1
        for v in range(1, N + 1):
            model += (x[i, j, v - 1] == 1).implies(puzzle[i, j] == v)
            model += (puzzle[i, j] == v).implies(x[i, j, v - 1] == 1)

# Latin square constraints via exact occurrence of each value in each row/column
for i in range(N):
    for v in range(N):
        model += cp.sum(x[i, :, v]) == 1

for j in range(N):
    for v in range(N):
        model += cp.sum(x[:, j, v]) == 1

# Pre-filled cells
for i in range(N):
    for j in range(N):
        if start_np[i, j] != 0:
            model += puzzle[i, j] == start_np[i, j]

