% Dual viewpoint: model the Costas array via row-position variables p[col]=row (a permutation), then enforce pairwise distinct displacement vectors for equal column separations; this is structurally different from the reference difference-triangle model but equivalent in solution space.
include "globals.mzn";

int: n = 8;

array[1..n] of var 1..n: costas;

% Permutation of rows: one mark per row and one per column
constraint all_different(costas);

% Distinct difference vectors: for any two equal column offsets l, the row differences must be all distinct
% If costas[i]-costas[i+l] == costas[j]-costas[j+l], then the vectors between the corresponding marks repeat.
constraint
  forall(l in 1..n-1)(
    let {
      int: m = n - l
    } in
      all_different([costas[i+l] - costas[i] | i in 1..m])
  );

solve satisfy;

output ["{\"costas\": ", show([costas[i] | i in 1..n]), "}"];

