% Strategy: model directly with {-1,+1} variables and use auxiliary binary product variables to linearize each periodic autocorrelation term; this is structurally distinct from the reference sum-of-products encoding while preserving the same feasible assignments.
int: l;
int: m = (l - 1) div 2;

array[1..l] of var -1..1: a;
array[1..l] of var -1..1: b;

constraint forall(i in 1..l)(a[i] != 0);
constraint forall(i in 1..l)(b[i] != 0);

constraint sum(i in 1..l)(a[i]) = 1;
constraint sum(i in 1..l)(b[i]) = 1;

array[1..m, 1..l] of var -1..1: pa;
array[1..m, 1..l] of var -1..1: pb;

constraint forall(s in 1..m, i in 1..l)(
    pa[s,i] = a[i] * a[((i + s - 1) mod l) + 1] /\
    pb[s,i] = b[i] * b[((i + s - 1) mod l) + 1]
);

constraint forall(s in 1..m)(
    sum(i in 1..l)(pa[s,i]) + sum(i in 1..l)(pb[s,i]) = -2
);

solve satisfy;

output [
  "{\"a\": ", show([a[i] | i in 1..l]), ", \"b\": ", show([b[i] | i in 1..l]), "}\n"
];

