% Strategy: dual-view reformulation using exact cover on row/column incidence with binary matrix variables and explicit row/column sum constraints.
include "globals.mzn";

array[int] of int: row_sums;
array[int] of int: col_sums;

int: R = length(row_sums);
int: C = length(col_sums);

array[1..R, 1..C] of var 0..1: matrix;

constraint
  forall(i in 1..R) (
    sum(j in 1..C)(matrix[i,j]) = row_sums[i]
  );

constraint
  forall(j in 1..C) (
    sum(i in 1..R)(matrix[i,j]) = col_sums[j]
  );

solve satisfy;

output [show(matrix)];

