array[1..r, 1..c] of var 0..1: matrix;

constraint forall(i in 1..r)(
    sum(j in 1..c)(matrix[i,j]) = if i = 1 then row_sums[i] + 1 else row_sums[i] endif
);

constraint forall(j in 1..c)(
    sum(i in 1..r)(matrix[i,j]) = col_sums[j]
);

constraint forall(i in 1..r)(
    matrix[i,1] = 0
);

solve satisfy;

output [
    "solution = {\"matrix\": ", show([[matrix[i,j] | j in 1..c] | i in 1..r]), "}\n"
];

