array[1..n] of var 0..9: digits;
var 2..10^n - 1: number;
var 1..9*n: root;

array[1..9*n] of int: cubes = [i*i*i | i in 1..9*n];

constraint number = sum(i in 1..n)(digits[i] * 10^(n - i));
constraint sum(i in 1..n)(digits[i]) = root;
constraint number = cubes[root];
constraint number > 1;

solve satisfy;

