% Strategy: dual edge-based connectivity encoding with cell colors as variables; enforce exact degree 1 on clues and degree 2 on empty cells, preserving the same feasible board fillings.
int: M = 5;
int: N = 5;

array[1..M, 1..N] of int: board = array2d(1..M, 1..N, [
  1,0,0,2,3,
  0,0,0,4,0,
  0,0,4,0,0,
  0,2,3,0,5,
  0,1,5,0,0
]);

array[1..M, 1..N] of var 1..5: B;
array[1..M, 1..N, 1..4] of var bool: adj;

constraint
  forall(i in 1..M, j in 1..N)(
    if board[i,j] != 0 then
      B[i,j] = board[i,j]
    else
      true
    endif
  );

constraint
  forall(i in 1..M, j in 1..N, d in 1..4)(
    adj[i,j,d] <-> (
      if d = 1 then i > 1 /\ B[i,j] = B[i-1,j]
      elseif d = 2 then j < N /\ B[i,j] = B[i,j+1]
      elseif d = 3 then i < M /\ B[i,j] = B[i+1,j]
      else j > 1 /\ B[i,j] = B[i,j-1]
      endif
    )
  );

constraint
  forall(i in 1..M, j in 1..N)(
    let {
      var 0..4: deg = sum(d in 1..4)(bool2int(adj[i,j,d]))
    } in
      if board[i,j] != 0 then
        deg = 1
      else
        deg = 2
      endif
  );

solve satisfy;

output ["{\"B\": ", show([[B[i,j] | j in 1..N] | i in 1..M]), "}"];

