# Strategy: dual viewpoint with an integer color grid only; enforce that every fixed cell keeps its color, every empty cell takes one of the 5 colors, and each non-terminal cell has exactly two orthogonally adjacent same-colored neighbors while each terminal has exactly one.
from cpmpy import *
import json

board = [[1, 0, 0, 2, 3],
         [0, 0, 0, 4, 0],
         [0, 0, 4, 0, 0],
         [0, 2, 3, 0, 5],
         [0, 1, 5, 0, 0]]

M = len(board)
N = len(board[0])

B = intvar(1, 5, shape=(M, N), name="B")
model = Model()

for i in range(M):
    for j in range(N):
        if board[i][j] != 0:
            model += (B[i, j] == board[i][j])

        neigh_same = []
        if i > 0:
            neigh_same.append(B[i, j] == B[i-1, j])
        if i < M-1:
            neigh_same.append(B[i, j] == B[i+1, j])
        if j > 0:
            neigh_same.append(B[i, j] == B[i, j-1])
        if j < N-1:
            neigh_same.append(B[i, j] == B[i, j+1])

        same_neighs = sum(neigh_same)

        if board[i][j] != 0:
            model += (same_neighs == 1)
        else:
            model += (same_neighs == 2)

model.solve()

solution = {"B": B.value().tolist()}
print(json.dumps(solution))

