        if i > 0:
            ns.append((i - 1, j))
        if i < n - 1:
            ns.append((i + 1, j))
        if j > 0:
            ns.append((i, j - 1))
        if j < n - 1:
            ns.append((i, j + 1))
        neighbors[(i, j)] = ns

