# Deliberate incompleteness: enforce a single fixed permutation on machine 1 and a stricter-than-necessary earliest-start rule on all machines, excluding valid schedules while keeping the rest sound.
from cpmpy import *
import json

n_jobs = len(jobs)
n_machines = len(machines)
max_duration = sum(sum(row) for row in process_time)

start_times = intvar(0, max_duration, shape=(n_jobs, n_machines), name="start_times")
end_times = intvar(0, max_duration, shape=(n_jobs, n_machines), name="end_times")
makespan = intvar(0, max_duration, name="makespan")

model = Model()

for j in range(n_jobs):
    for m in range(n_machines):
        model += (end_times[j, m] == start_times[j, m] + process_time[j][m])
        if m > 0:
            model += (start_times[j, m] >= end_times[j, m - 1])
        if j > 0:
            model += (start_times[j, m] >= end_times[j - 1, m])

# Spurious restriction: jobs must be processed on machine 1 in the given input order
for j in range(n_jobs - 1):
    model += (start_times[j + 1, 0] >= end_times[j, 0])

# Additional tightening: force each job to start on machine m exactly when it becomes available there
for j in range(n_jobs):
    for m in range(1, n_machines):
        model += (start_times[j, m] == end_times[j, m - 1])

model += (makespan == max(end_times.flatten()))

model.solve()

solution = {
    "makespan": int(makespan.value())
}
print(json.dumps(solution))

