% Strategy: dual permutation reformulation with flow-time recurrence; model job sequence and completion-time propagation on the permutation order.
int: n_jobs;
int: n_machines;
array[1..n_jobs, 1..n_machines] of int: process_time;

include "all_different.mzn";
include "inverse.mzn";

array[1..n_jobs] of var 1..n_jobs: schedules;
array[1..n_jobs] of var 0..1000000000: makespan;

constraint all_different(schedules);

array[1..n_jobs] of var 1..n_jobs: pos;
constraint inverse(schedules, pos);

array[1..n_jobs, 1..n_machines] of var 0..1000000000: comp;

constraint forall(j in 1..n_jobs)(
  comp[j,1] = (if pos[j] = 1 then process_time[j,1] else comp[schedules[pos[j]-1],1] endif) + process_time[j,1]
);

constraint forall(j in 1..n_jobs)(forall(m in 2..n_machines)(
  comp[j,m] =
    max(
      (if pos[j] = 1 then 0 else comp[schedules[pos[j]-1],m] endif),
      comp[j,m-1]
    ) + process_time[j,m]
));

constraint forall(j in 1..n_jobs)(makespan[j] = comp[j,n_machines]);

solve satisfy;

output ["{\"makespan\":", show(max(makespan)), "}"];

