% Incompleteness strategy: restrict the job sequence to be lexicographically nondecreasing, which excludes valid permutations while keeping the flow-shop timing constraints sound.
int: n_jobs;
int: n_machines;
array[1..n_jobs, 1..n_machines] of int: process_time;

array[1..n_jobs] of var 1..n_jobs: schedules;
var 0..sum(i in 1..n_jobs, m in 1..n_machines)(process_time[i,m]): makespan;

constraint forall(i in 1..n_jobs-1)(schedules[i] <= schedules[i+1]);

constraint all_different(schedules);

array[1..n_jobs, 1..n_machines] of var 0..sum(i in 1..n_jobs, m in 1..n_machines)(process_time[i,m]): start;
array[1..n_jobs, 1..n_machines] of var 0..sum(i in 1..n_jobs, m in 1..n_machines)(process_time[i,m]): finish;

constraint forall(pos in 1..n_jobs)(
  forall(m in 1..n_machines)(
    let {
      var 1..n_jobs: j = schedules[pos]
    } in
      if pos = 1 /\ m = 1 then
        start[pos,m] = 0
      elseif pos = 1 then
        start[pos,m] = finish[pos,m-1]
      elseif m = 1 then
        start[pos,m] = finish[pos-1,m]
      else
        start[pos,m] = max(finish[pos-1,m], finish[pos,m-1])
      endif /\
      finish[pos,m] = start[pos,m] + process_time[j,m]
  )
