  let {
    var 1..n_jobs: prev_job = schedules[k-1],
    var 1..n_jobs: cur_job = schedules[k]
  } in
    start_time[cur_job,1] >= end_time[prev_job,1]
);

constraint forall(m in 1..n_machines)(
  start_time[schedules[1], m] = 0
);

constraint forall(k in 2..n_jobs)(
  schedules[k-1] < schedules[k]
);

constraint forall(m in 1..n_machines)(
  forall(k in 1..n_jobs-1)(
    let {
      var 1..n_jobs: j1 = schedules[k],
