array[1..n] of var 0..3: export;
array[1..n] of var 0..3: attraction;

constraint alldifferent(island);
constraint alldifferent(export);
constraint alldifferent(attraction);

% Names: Pwana, Quero, Rayou, Skern
% Exports: alabaster, bananas, coconuts, durian fruit
% Attractions: hotel, ice skating rink, jai alai stadium, koala preserve

% 1. koala preserve is due south of Pwana.
constraint attraction[4] = island[1] + 1;

% 2. alabaster quarry is due west of Quero.
constraint export[1] = island[2] - 1;

% 3. hotel is due east of durian fruit.
constraint attraction[1] = export[4] + 1;

% 4. Skern and jai alai stadium are connected by a north-south bridge.
constraint abs(island[4] - attraction[3]) = 1;

% 5. Rayou and bananas are connected by an east-west bridge.
constraint abs(island[3] - export[2]) = 1;

% 6. ice skating rink and jai alai stadium are not connected by a bridge.
constraint abs(attraction[2] - attraction[3]) != 1;

solve satisfy;

output [
  "{",
  "\"island\": ", show(island), ", ",
  "\"export\": ", show(export), ", ",
  "\"attraction\": ", show(attraction),
  "}"
];

