% Incompleteness strategy: over-restrict the export->island mapping by forcing the durian exporter to be island 3, which excludes some valid solutions while keeping all posted constraints consistent.
int: n = 4;
set of int: I = 0..n-1;

array[I] of var I: island;
array[I] of var I: export;
array[I] of var I: attraction;

constraint all_different(island);
constraint all_different(export);
constraint all_different(attraction);

% Map positions: 0=A, 1=B, 2=C, 3=D
% A north of B, C west of D, and the corresponding bridges exist only between these pairs.
% We encode relations using the position indices.
function var bool: north_of(var int: x, var int: y) = x = y - 1;
function var bool: south_of(var int: x, var int: y) = x = y + 1;
function var bool: west_of(var int: x, var int: y) = x = y - 2;
function var bool: east_of(var int: x, var int: y) = x = y + 2;

% 1. Koala preserve is due south of Pwana.
constraint south_of(attraction[3], island[0]);

% 2. Alabaster quarry is due west of Quero.
constraint west_of(export[0], island[1]);

% 3. Resort hotel is due east of durian exporter.
constraint east_of(attraction[1], export[3]);

% 4. Skern and jai alai stadium are connected by a north-south bridge.
constraint ( (island[3] = attraction[2] + 1) \/ (island[3] = attraction[2] - 1) );

% 5. Rayou and bananas exporter are connected by an east-west bridge.
constraint ( (island[2] = export[1] + 2) \/ (island[2] = export[1] - 2) );

% 6. Ice skating rink and jai alai stadium are not connected by a bridge.
constraint not ( (attraction[0] = attraction[2] + 1) \/ (attraction[0] = attraction[2] - 1)
              \/ (attraction[0] = attraction[2] + 2) \/ (attraction[0] = attraction[2] - 2) );

% Deliberate incompleteness: restrict the durian exporter to island D (3).
constraint export[3] = 3;

solve satisfy;

output [
  "{",
  "\"island\": ", show(island), ", ",
  "\"export\": ", show(export), ", ",
  "\"attraction\": ", show(attraction),
  "}"
];

