% Flaw strategies: relax the subset-sum link by only requiring each target number to be bounded above by a subset sum, and omit the restriction that a subset must actually be selected.
array[1..1] of int: numbers = [0];

int: m = length(numbers);
int: n = 3;

array[1..n] of var 1..10: x;
array[1..m, 1..n] of var 0..1: tmp;

constraint
  forall(i in 1..m)(
    sum(j in 1..n)(tmp[i, j] * x[j]) >= numbers[i]
  );

solve satisfy;

output ["{\"x\": [" ++ concat([if j > 1 then ", " else "" endif ++ show(fix(x[j])) | j in 1..n]) ++ "]}"];

