array[1..n, 1..3] of var 0..1: b;
array[1..n] of var 1..10: s;

constraint forall(i in 1..n) (
  s[i] = sum(j in 1..3)(b[i, j] * x[j]) /\
  s[i] = numbers[i]
);

solve satisfy;

output ["{\"x\":", show([x[j] | j in 1..3]), "}"];

