% Strategy: direct cell grid only; enforce Latin-square constraints with global alldifferent on rows and columns, plus explicit fixed values and adjacency inequalities derived from lt.

include "alldifferent.mzn";

int: n = 5;
array[1..11, 1..4] of int: lt;
array[1..5, 1..5] of int: values;

array[1..n, 1..n] of var 1..n: grid;

constraint forall(r in 1..n)(
  alldifferent([grid[r,c] | c in 1..n])
);

constraint forall(c in 1..n)(
  alldifferent([grid[r,c] | r in 1..n])
);

constraint forall(r in 1..n, c in 1..n)(
  values[r,c] > 0 -> grid[r,c] = values[r,c]
);

constraint forall(k in 1..11)(
  let {
    int: r1 = lt[k,1],
    int: c1 = lt[k,2],
    int: r2 = lt[k,3],
    int: c2 = lt[k,4]
  } in
    if r1 = r2 /\ c1 + 1 = c2 then
      grid[r1,c1] < grid[r2,c2]
    elseif r1 = r2 /\ c2 + 1 = c1 then
      grid[r2,c2] < grid[r1,c1]
    elseif c1 = c2 /\ r1 + 1 = r2 then
      grid[r1,c1] < grid[r2,c2]
    elseif c1 = c2 /\ r2 + 1 = r1 then
      grid[r2,c2] < grid[r1,c1]
    else
      true
    endif
);

solve satisfy;

output ["{\"grid\":", show(grid), "}"];

