array[1..n, 1..n] of var 1..n: row_of;   % row_of[c,d] = row where digit d appears in column c

constraint forall(r in 1..n)(alldifferent([grid[r,c] | c in 1..n]));
constraint forall(c in 1..n)(alldifferent([grid[r,c] | r in 1..n]));

constraint forall(r in 1..n, d in 1..n)(
    sum(c in 1..n)(bool2int(grid[r,c] = d)) = 1
);
constraint forall(c in 1..n, d in 1..n)(
    sum(r in 1..n)(bool2int(grid[r,c] = d)) = 1
);

constraint forall(r in 1..n, d in 1..n)(
    pos[r,d] = sum(c in 1..n)(c * bool2int(grid[r,c] = d))
);
constraint forall(c in 1..n, d in 1..n)(
    row_of[c,d] = sum(r in 1..n)(r * bool2int(grid[r,c] = d))
);

constraint forall(r in 1..n, c in 1..n)(
    values[r,c] > 0 -> grid[r,c] = values[r,c]
);

constraint forall(k in 1..11)(
    let {
        int: r1 = lt[k,1],
        int: c1 = lt[k,2],
        int: r2 = lt[k,3],
        int: c2 = lt[k,4]
    } in
    if r1 = r2 /\ c1 + 1 = c2 then
        grid[r1,c1] < grid[r2,c2]
    elseif r1 = r2 /\ c2 + 1 = c1 then
        grid[r2,c2] < grid[r1,c1]
    elseif c1 = c2 /\ r1 + 1 = r2 then
        grid[r1,c1] < grid[r2,c2]
    elseif c1 = c2 /\ r2 + 1 = r1 then
        grid[r2,c2] < grid[r1,c1]
    else
        true
    endif
);

solve satisfy;

output ["{\"grid\":", show(grid), "}"];

