# Flaw 1 (unsound): weaken row uniqueness to only adjacent inequality, which allows repeated values in a row; Flaw 2 (incomplete): add an extra strict constraint tying two corner cells, excluding valid solutions that do not satisfy it.
from cpmpy import *
import numpy as np
import json

size = len(values)
RANGE = list(range(size))
NUMQD = list(range(len(lt)))

grid = intvar(1, size, shape=(size, size), name="field")

model = Model()

for row in RANGE:
    for col in RANGE:
        if values[row][col] > 0:
            model += (grid[row, col] == values[row][col])

# Unsound relaxation: replace row AllDifferent with only neighbor-inequality constraints
for row in RANGE:
    for col in range(size - 1):
        model += (grid[row, col] != grid[row, col + 1])

# Keep column all-different as in the intended model
for col in RANGE:
    model += AllDifferent([grid[row, col] for row in RANGE])

# All given inequality constraints
for i in NUMQD:
    model += (grid[lt[i][0] - 1, lt[i][1] - 1] < grid[lt[i][2] - 1, lt[i][3] - 1])

# Incomplete restriction: force top-left to be smaller than bottom-right, excluding valid solutions that violate it
model += (grid[0, 0] < grid[size - 1, size - 1])

model.solve()

solution = {
    "grid": grid.value().tolist()
}
print(json.dumps(solution))

