% Strategy: direct sequence model with position-indexed integer variables and transition constraints for +5, +7, or exact integer sqrt steps.
int: n = 24;
array[1..n] of var 0..60: x;

constraint x[1] = 0;
constraint x[n] = 14;
constraint forall(i in 1..n, j in i+1..n)(x[i] != x[j]);

constraint forall(i in 1..n-1)(
  (x[i+1] = x[i] + 5 /\ x[i+1] <= 60)
  \/
  (x[i+1] = x[i] + 7 /\ x[i+1] <= 60)
  \/
  (x[i+1] * x[i+1] = x[i] /\ x[i+1] >= 0)
);

constraint exists(i in 1..n)(x[i] = 2);
constraint exists(i in 1..n)(x[i] = 10);
constraint exists(i in 1..n)(x[i] = 14);

constraint let {
  array[1..3] of int: target = [2, 10, 14]
} in
forall(k in 1..2)(
  exists(i, j in 1..n)(i < j /\ x[i] = target[k] /\ x[j] = target[k+1])
);

solve satisfy;

output ["{\"x\":", show(x), "}"];

