0, 39, 0, 0, 0, 0, 78, 73, 71, 85, 69, 0,
35, 0, 0, 46, 53, 0, 0, 0, 80, 84, 0, 0,
36, 0, 45, 0, 0, 52, 51, 0, 0, 0, 0, 88
]);

array[1..r, 1..c] of var 1..r*c: x;

constraint alldifferent(array1d(x));

constraint forall(i in 1..r, j in 1..c where puzzle[i,j] > 0) (
  x[i,j] = puzzle[i,j]
);

constraint forall(k in 1..r*c-1)(
  let {
    array[1..r,1..c] of var bool: is_k = array2d(1..r,1..c, [x[i,j] = k | i in 1..r, j in 1..c]),
    array[1..r,1..c] of var bool: is_k1 = array2d(1..r,1..c, [x[i,j] = k+1 | i in 1..r, j in 1..c])
  } in
  exists(i in 1..r, j in 1..c, di in -1..1, dj in -1..1 where not (di = 0 /\ dj = 0)) (
    is_k[i,j] /\
    let {
      int: ni = i + di,
      int: nj = j + dj
    } in
      ni >= 1 /\ ni <= r /\ nj >= 1 /\ nj <= c /\ is_k1[ni,nj]
  )
);

% Deliberate incompleteness: force the first row to be nondecreasing, excluding valid solutions
constraint forall(j in 1..c-1)(
  x[1,j] <= x[1,j+1]
);

solve satisfy;

output ["x = ", show([ [ x[i,j] | j in 1..c ] | i in 1..r ]), ";\n"];

