unsound-incomplete.code:
# Flaw 1 (unsoundness): relax some AllDifferent constraints to pairwise inequality only for segments of length > 2, allowing duplicates in longer entries.
# Flaw 2 (incompleteness): additionally force all cells on the main diagonal to be nonzero whenever they are part of a segment, which excludes some valid solutions.
from cpmpy import *
import json

model = Model()

x = intvar(0, 9, shape=(n, n), name="x")

# fill the blanks with 0
for i in range(num_blanks):
    model += x[blanks[i][0] - 1, blanks[i][1] - 1] == 0

for i in range(num_p):
    segment = problem[i][1::]
    res = problem[i][0]
    cells = [x[j[0] - 1, j[1] - 1] for j in segment]

    for v in cells:
        model += v >= 1

    model += sum(cells) == res

    # Deliberate flaw: weaken uniqueness for longer segments
    if len(cells) <= 2:
        model += AllDifferent(cells)
    else:
        for a in range(len(cells)):
            for b in range(a + 1, len(cells)):
                model += cells[a] != cells[b] if (a == 0 or b == 0) else (cells[a] + cells[b] >= 2)

    # Deliberate flaw: over-constrain diagonal cells that appear in any segment
    for j in segment:
        if j[0] == j[1]:
            model += x[j[0] - 1, j[1] - 1] >= 2

model.solve()

solution = {
    'x': x.value().tolist()
}
print(json.dumps(solution, indent=4))

