int: n;
int: num_p;
array[1..num_p] of int: problem_target;
array[1..num_p] of int: problem_size;
array[1..num_p, 1..10] of int: problem_pos;

array[1..n, 1..n] of var 1..n: x;

constraint
  forall(r in 1..n)(
    all_different([x[r,c] | c in 1..n])
  ) /\
  forall(c in 1..n)(
    all_different([x[r,c] | r in 1..n])
  );

constraint
  forall(p in 1..num_p)(
    let {
      int: target = problem_target[p],
      int: k = problem_size[p],
      array[1..k] of int: rr = [ problem_pos[p, 2*i-1] | i in 1..k ],
      array[1..k] of int: cc = [ problem_pos[p, 2*i] | i in 1..k ],
      array[1..k] of var 1..n: cells = [ x[rr[i], cc[i]] | i in 1..k ],
      var 1..(n*k): s = sum(i in 1..k)(cells[i]),
      var 1..(n^k): pr = product(i in 1..k)(cells[i])
    } in
      (
        (k = 1 /\ cells[1] = target)
      \/
        (k = 2 /\ (cells[1] + cells[2] = target \/ abs(cells[1] - cells[2]) = target \/ cells[1] * cells[2] = target \/ max(cells[1], cells[2]) div min(cells[1], cells[2]) = target \/ max(cells[1], cells[2]) mod min(cells[1], cells[2]) = 0 /\ max(cells[1], cells[2]) div min(cells[1], cells[2]) = target))
      \/
        (k > 2 /\ (s = target \/ pr = target))
      )
  );

solve satisfy;

output ["{\"x\":", show([ [ x[r,c] | c in 1..n ] | r in 1..n ]), "}"];

