% Flaw 1 (unsound): allow up to one unit of unmet demand per destination-product.
% Flaw 2 (incomplete): force each origin-product to ship exactly its full supply, excluding valid partial-shipment solutions.
int: O = 2;
int: D = 2;
int: P = 2;

array[1..O, 1..P] of int: supply = array2d(1..O, 1..P, [20, 30, 40, 10]);
array[1..D, 1..P] of int: demand = array2d(1..D, 1..P, [30, 30, 30, 10]);
array[1..O, 1..D, 1..P] of int: cost = array3d(1..O, 1..D, 1..P,
    [2, 3, 4, 1,
     3, 2, 2, 4]);

array[1..O, 1..D, 1..P] of var 0..1000: x;
array[1..D, 1..P] of var 0..1: shortage;
var 0..1000000: total_cost;

constraint
  forall(i in 1..O, p in 1..P) (
    sum(j in 1..D)(x[i,j,p]) = supply[i,p]
  );

constraint
  forall(j in 1..D, p in 1..P) (
    sum(i in 1..O)(x[i,j,p]) + shortage[j,p] = demand[j,p]
  );

constraint
  forall(j in 1..D, p in 1..P) (
    shortage[j,p] <= 1
  );

constraint
  total_cost = sum(i in 1..O, j in 1..D, p in 1..P)(
    x[i,j,p] * cost[i,j,p]
  );

solve satisfy;

output ["{\"total_cost\":" ++ show(total_cost) ++ "}"];

