# Flaw strategy: weaken the transition by allowing the blank to stay in place in one step if all other tiles match; this admits non-moving (frozen) intermediate states while preserving start/end and all other valid solutions.
from cpmpy import *
import json
import numpy as np

def n_puzzle(puzzle_start, puzzle_end, N_STEPS):
    m = Model()

    (dim, dim2) = puzzle_start.shape
    assert dim == dim2, "puzzle needs square shape"
    n = dim * dim2 - 1

    x = intvar(0, n, shape=(N_STEPS, dim, dim), name="x")

    m += (x[0] == puzzle_start)
    m += (x[-1] == puzzle_end)

    def neigh(i, j):
        for (rr, cc) in [(0, 0), (-1, 0), (1, 0), (0, -1), (0, 1)]:
            if 0 <= i + rr < dim and 0 <= j + cc < dim:
                yield i + rr, j + cc

    def transition(m, prev_x, next_x):
        for i in range(dim):
            for j in range(dim):
                m += (next_x[i, j] == 0).implies(any(prev_x[r, c] == 0 for r, c in neigh(i, j)))

        m += AllDifferent(next_x)

        m += ((prev_x == 0) | (next_x == 0) | (prev_x == next_x))

        # Deliberate unsoundness: allow exactly-equal consecutive states as a special case
        # when the blank is adjacent to itself under the reachability check above.
        m += any(prev_x != next_x) | (np.sum(prev_x == 0) == 1)

    for i in range(1, N_STEPS):
        transition(m, x[i - 1], x[i])

    return (m, x)

