print(json.dumps(solution))

# Flaw strategy: weaken the transition by enforcing tile-wise local consistency except for the blank, which may teleport to any adjacent-or-current cell without requiring the swapped tile to move correspondingly.
from cpmpy import *
import json
import numpy as np

def n_puzzle(puzzle_start, puzzle_end, N_STEPS):
    m = Model()

    (dim, dim2) = puzzle_start.shape
    assert dim == dim2, "puzzle needs square shape"
    n = dim * dim2 - 1

    x = intvar(0, n, shape=(N_STEPS, dim, dim), name="x")

    m += (x[0] == puzzle_start)
    m += (x[-1] == puzzle_end)

    def neigh(i, j):
        for (rr, cc) in [(0, 0), (-1, 0), (1, 0), (0, -1), (0, 1)]:
            if 0 <= i + rr < dim and 0 <= j + cc < dim:
                yield i + rr, j + cc

    def transition(m, prev_x, next_x):
        # Every tile in next state must come from the same position,
        # except the blank, which is only required to be reachable from a neighboring blank.
        for i in range(dim):
            for j in range(dim):
                m += (next_x[i, j] == 0).implies(any(prev_x[r, c] == 0 for r, c in neigh(i, j)))

        m += AllDifferent(next_x)

        # Deliberate unsoundness: only constrain non-zero tiles to be preserved when neither side is blank.
        # This omits the mandatory swap relation between the blank and the moved tile.
        for i in range(dim):
            for j in range(dim):
                m += ((prev_x[i, j] != 0) & (next_x[i, j] != 0)).implies(prev_x[i, j] == next_x[i, j])

        # Still forbid freezing.
        m += any(prev_x != next_x)

    for i in range(1, N_STEPS):
        transition(m, x[i - 1], x[i])

    return (m, x)

