# Strategy: invert the move relation by tracking, for each time step, the position of each tile value (including the blank) and enforce that every consecutive board differs by exactly one blank-adjacent swap via a transition table.
from pycsp3 import *

r = len(puzzle_start)
c = len(puzzle_start[0])
n = r * c
tiles = range(n)

steps = VarArray(size=[N_STEPS, r, c], dom=tiles)
pos = VarArray(size=[N_STEPS, n, 2], dom=[range(r), range(c)])

adjacent_pairs = []
for i in range(r):
    for j in range(c):
        for ii in range(r):
            for jj in range(c):
                if abs(i - ii) + abs(j - jj) == 1:
                    adjacent_pairs.append((i, j, ii, jj))

def cell_value(t, i, j):
    return steps[t][i][j]

satisfy(
    # each board is a permutation of all tiles
    [AllDifferent([steps[t][i][j] for i in range(r) for j in range(c)]) for t in range(N_STEPS)],

    # link positions to board values
    [
        [steps[t][pos[t][v][0]][pos[t][v][1]] == v for v in tiles]
        for t in range(N_STEPS)
    ],

    # fixed start and end boards
    [steps[0][i][j] == puzzle_start[i][j] for i in range(r) for j in range(c)],
    [steps[N_STEPS - 1][i][j] == puzzle_end[i][j] for i in range(r) for j in range(c)],

    # no freezing: every consecutive pair must differ
    [Any([steps[t][i][j] != steps[t + 1][i][j] for i in range(r) for j in range(c)]) for t in range(N_STEPS - 1)],

    # exactly one legal swap of the blank with an orthogonally adjacent tile at each step
    [
        Or(
            [
                And(
                    steps[t][i][j] == 0,
                    steps[t + 1][ii][jj] == 0,
                    steps[t + 1][i][j] == steps[t][ii][jj],
                    steps[t + 1][ii][jj] == steps[t][i][j]
                )
                for (i, j, ii, jj) in adjacent_pairs
            ]
        )
        for t in range(N_STEPS - 1)
    ]
)

