# Strategy: encode timewise overlap constraints via pairwise disjunctions on intervals, using direct room variables and preassignment fixing.
import pandas as pd
from cpmpy import *
import numpy as np
import json

data = {
    "start": pd.to_datetime(start_data),
    "end": pd.to_datetime(end_data),
    "room": [r if r != -1 else np.nan for r in preassigned_room_data]
}
df = pd.DataFrame(data)

def model_rooms(df, max_rooms):
    n_requests = len(df)
    room_assignments = intvar(0, max_rooms - 1, shape=n_requests)

    m = Model()

    for idx, row in df.iterrows():
        if not pd.isna(row["room"]):
            m += (room_assignments[idx] == int(row["room"]))

    starts = list(df["start"])
    ends = list(df["end"])

    for i in range(n_requests):
        for j in range(i + 1, n_requests):
            if starts[i] < ends[j] and starts[j] < ends[i]:
                m += (room_assignments[i] != room_assignments[j])

    return m, room_assignments

model, room_assignments = model_rooms(df, max_rooms)
model.solve()

solution = {"room_assignments": room_assignments.value().tolist()}
print(json.dumps(solution))

