# Strategy: dual viewpoint with membership booleans; enforce independence and maximality via neighborhood coverage
from cpmpy import *
import json

adjacency_list = [[2, 3, 7], [1, 4, 8], [1, 4, 5], [2, 3, 6], [3, 6, 7], [4, 5, 8], [1, 5, 8], [2, 6, 7]]
n = 8

nodes = boolvar(shape=n, name="nodes")
model = Model()

# Independent set: no adjacent pair can both be selected
for i, neighbors in enumerate(adjacency_list):
    for neighbor in neighbors:
        j = neighbor - 1
        if i < j:
            model += ~(nodes[i] & nodes[j])

# Maximality: every unselected node must have at least one selected neighbor
for i, neighbors in enumerate(adjacency_list):
    if neighbors:
        model += nodes[i] | any(nodes[j - 1] for j in neighbors)

model.solve()

solution = {"nodes": nodes.value().tolist()}
print(json.dumps(solution))

