# Unsoundness strategy: only enforce non-overlap for the first conflicting pair of movies encountered; all later overlaps are ignored, so some invalid schedules are admitted while many valid ones remain feasible.
from cpmpy import *
import json

num_movies = len(movies)

selected_movies = boolvar(shape=num_movies, name="selected_movies")

model = Model()

added_first_conflict = False
for i in range(num_movies):
    for j in range(i + 1, num_movies):
        if (movies[i][2] > movies[j][1]) and (movies[j][2] > movies[i][1]):
            if not added_first_conflict:
                model += selected_movies[i] + selected_movies[j] <= 1
                added_first_conflict = True

model.solve()

solution = {"selected_movies": selected_movies.value().tolist()}
print(json.dumps(solution))

