% Strategy: dual permutation model with one array per category mapping each entity to its assigned label; post the clues as inverse-position arithmetic constraints on these permutations.
include "alldifferent.mzn";

int: n = 5;

array[1..n] of var 1..n: ages;      % children -> age label
array[1..n] of var 1..n: children;   % children -> child identity (fixed by position, kept as a permutation for output compatibility)
array[1..n] of var 1..n: countries;  % children -> country
array[1..n] of var 1..n: stories;    % children -> story

array[1..n] of var 1..n: pos_stories = array1d(1..n, [sum(i in 1..n)(if stories[i] = s then i else 0 endif) | s in 1..n]);
array[1..n] of var 1..n: pos_countries = array1d(1..n, [sum(i in 1..n)(if countries[i] = c then i else 0 endif) | c in 1..n]);

