% Strategy: model prefix counts of females and enforce the ratio on every nonempty prefix; this is a dual/time-state encoding rather than a direct adjacency/order rule.
int: n = 13;
array[1..n] of var bool: sequence;

array[0..n] of var 0..n: females_prefix;
constraint females_prefix[0] = 0;
constraint forall(i in 1..n) (
    females_prefix[i] = females_prefix[i-1] + bool2int(sequence[i])
);

% Total composition: 9 females and 4 males.
constraint females_prefix[n] = 9;

% For every prefix, females / males <= 7 / 3.
