# Strategy: structurally distinct CPMpy formulation using 3D one-hot cell encoding with channeling to the visible grid; preserves exactly the same Sudoku solution set.
from cpmpy import *
import json
import numpy as np

e = 0
given = np.array(input_grid)

# Visible solution grid
grid = intvar(1, 9, shape=(9, 9), name="grid")

# Auxiliary one-hot encoding: x[r,c,d] = 1 iff cell (r,c) takes digit d+1
x = boolvar(shape=(9, 9, 9), name="x")

model = Model()

# Channeling between grid and one-hot variables
for r in range(9):
    for c in range(9):
        model += sum(x[r, c, d] for d in range(9)) == 1
        model += grid[r, c] == sum((d + 1) * x[r, c, d] for d in range(9))

# Given clues
for r in range(9):
    for c in range(9):
        if given[r, c] != e:
            model += grid[r, c] == given[r, c]

# Each digit appears exactly once in every row
for r in range(9):
    for d in range(9):
        model += sum(x[r, c, d] for c in range(9)) == 1

# Each digit appears exactly once in every column
for c in range(9):
    for d in range(9):
        model += sum(x[r, c, d] for r in range(9)) == 1

# Each digit appears exactly once in every 3x3 block
for br in range(3):
    for bc in range(3):
        for d in range(9):
            model += sum(x[r, c, d] for r in range(3 * br, 3 * br + 3) for c in range(3 * bc, 3 * bc + 3)) == 1

model.solve()

solution = {"grid": grid.value().tolist()}
print(json.dumps(solution))

