# Strategy: state-transition CP with explicit move variable and table-encoded legal crossings; safety enforced by shore-state forbidden patterns.
from pycsp3 import *

n = stage

wolf_pos = VarArray(size=n, dom=range(2))
goat_pos = VarArray(size=n, dom=range(2))
cabbage_pos = VarArray(size=n, dom=range(2))
boat_pos = VarArray(size=n, dom=range(2))

move = VarArray(size=n - 1, dom=range(4))  # 0=wolf, 1=goat, 2=cabbage, 3=farmer alone

def allowed_transition(b, w, g, c, m, nb, nw, ng, nc):
    if nb != 1 - b:
        return False
    if m == 3:
        return (nw, ng, nc) == (w, g, c)
    if m == 0:
        return w == b and nw == 1 - w and ng == g and nc == c
    if m == 1:
        return g == b and nw == w and ng == 1 - g and nc == c
    if m == 2:
        return c == b and nw == w and ng == g and nc == 1 - c
    return False

T = [
    (b, w, g, c, m, 1 - b,
     1 - w if m == 0 else w,
     1 - g if m == 1 else g,
     1 - c if m == 2 else c)
    for b in range(2)
    for w in range(2)
    for g in range(2)
    for c in range(2)
    for m in range(4)
    if (m == 3 or (m == 0 and w == b) or (m == 1 and g == b) or (m == 2 and c == b))
]

satisfy(
    wolf_pos[0] == 0,
    goat_pos[0] == 0,
    cabbage_pos[0] == 0,
    boat_pos[0] == 0,

    wolf_pos[n - 1] == 1,
    goat_pos[n - 1] == 1,
    cabbage_pos[n - 1] == 1,
    boat_pos[n - 1] == 1,

    [
        (wolf_pos[t] != goat_pos[t]) | (boat_pos[t] == wolf_pos[t])
        for t in range(n)
    ],
    [
        (goat_pos[t] != cabbage_pos[t]) | (boat_pos[t] == goat_pos[t])
        for t in range(n)
    ],

    [
        Table(
            [boat_pos[t], wolf_pos[t], goat_pos[t], cabbage_pos[t], move[t],
             boat_pos[t + 1], wolf_pos[t + 1], goat_pos[t + 1], cabbage_pos[t + 1]],
            T
        )
        for t in range(n - 1)
    ]
)

